// The 'webviews' service: web views (a browser's content) placed over elements of the page. Two
// backends behind one contract (WebView in types.ts):
//
// - native: the Mac app registers `webkit.messageHandlers.tilrWebViews` (WebViews.swift). A view
//   is a WKWebView of the app's, a subview of the page's, placed at the host's rect on screen;
//   the page posts { op, id, … } (create, place, navigate, back, forward, reload, stop, dispose)
//   and the app reports back through a 'tilr-webview' CustomEvent on `window` (the view's
//   state, or a request to open a URL in a new window). `create` carries the view's profile
//   whole: the app gives each profile a data store of its own and sets the profile's proxy on
//   it before the view loads (a tunnel, a tilr server's /socks, through a SOCKS port of the
//   app's); the state reports the proxy's kind and a tunnel's failed handshake. The view follows its host: measured
//   again when the host resizes, the layout changes, a transition ends, the page scrolls. The
//   views are AppKit subviews, above the whole page, so the page's stacking goes with the
//   place: the order of the views (the layout's z-index: floats over tiles, the focused float
//   on top) and the holes, where a window or the drop preview stacked above the host covers
//   it, or an overlay (ctx.ui.overlay(), ctx.ui.popup(): a menu, a dropdown) is shown; the app
//   masks the view there and lets the clicks through to the page. A press in the
//   view is the view's; the app reports it and the service tells it as a pointerdown on the
//   host, so the layout focuses the window as on a press anywhere else in it.
//   A view made with a `key` (stable across reloads: a browser window's id) outlives a reload of
//   the page: the app parks it (hidden, media suspended) for `browser.adopt_grace` seconds, and
//   the new page's `create` with the same key and profile adopts it. The app then loads nothing
//   (the create's `url` is ignored: the live view is at least as recent as the page's saved
//   URL) and answers with the whole state and `adopted: true`; the view takes it as is.
//   A view hidden for `browser.discard_after` seconds (not visible, covered, parked) releases its
//   web content: the app reports `discarded: true` (its last picture stays in place) and, once
//   a place shows it again, `discarded: false` while it loads its page again (history, scroll).
// - iframe: anywhere else (a browser, the tests) the view is an <iframe> in the host. A page
//   from another origin is opaque: no title, no URL, no history, and a site that forbids
//   framing shows nothing. A same-origin page (the site's own files) reports all of it. A
//   profile is taken and left: the frame's storage and network are the browser's.
//
// A positioned child of <body> (a menu panel, a dialog) stacked above the host's window is a
// layer on its own, a hole like a window above: #grid and the canvas make no stacking context,
// so its z-index and the windows' compare directly. A nested element (inside a tile, the header,
// a shadow root) is still under the native view unless marked with ctx.ui.overlay().
import { Service } from 'cordis'
import type { Context } from 'cordis'
import type { TilrPluginClass, WebView, WebViewFeatures, WebViewOptions, WebViewState, WebViews as WebViewsApi } from 'tilr'
import { nativeChannel } from 'tilr/native'

/** The app's message handler, and the event it answers with. */
export const HANDLER = 'tilrWebViews'
export const EVENT = 'tilr-webview'

/** What the app sends: the view's state (any subset of the fields), an open request, or a
 *  press: a mouse button down in the view, which the page never sees itself. */
export interface NativeEvent extends Partial<WebViewState> {
  id: string
  type?: 'state' | 'open' | 'press'
  /** For 'open': the URL the page asked a new window for. */
  open?: string
  /** On the first report of a view the app gave back from before a reload (`key`). */
  adopted?: boolean
}

/** A rect in CSS px. */
export interface Box { x: number, y: number, width: number, height: number }
/** A rect of the viewport, CSS px, as the app places a view: `z` orders the views among
 *  themselves as the page stacks their hosts, `holes` (relative to the view) are where the page
 *  draws over the host, which the view leaves to the page. */
export interface Placement extends Box { visible: boolean, z: number, holes: Box[] }

/** The layout's stacking: the windows (tiles at 0, floats above, the focused one on top, by
 *  z-index) and the drop preview, the canvas's children. The view's own window is the one its
 *  host is in. */
const LAYERS = '.tilr-canvas > .window, .tilr-canvas > .drop'

/** Where `host` is on screen, whole pixels inside the element (a fractional edge rounded
 *  outwards would put the view over the frame's 1px border next to it), whether it is shown at
 *  all, and what the page stacks over it (`overlays`: over everything). */
export function placement(host: HTMLElement, overlays: HTMLElement[] = []): Placement {
  const rect = host.getBoundingClientRect()
  const shown = host.isConnected && rect.width > 0 && rect.height > 0 && (host.checkVisibility?.() ?? true)
  const x = Math.ceil(rect.left)
  const y = Math.ceil(rect.top)
  const box = { x, y, width: Math.max(0, Math.floor(rect.right) - x), height: Math.max(0, Math.floor(rect.bottom) - y) }
  return { ...box, visible: shown, ...stacking(host, box, overlays) }
}

/** A child of <body> is a layer if it is positioned (fixed, absolute) and is not what holds
 *  the host (#grid). One with `pointer-events: none` is a transparent container (a full-screen
 *  layer for toasts): what it holds is nested, marked with ctx.ui.overlay() if it covers views. */
function bodyLayer(el: HTMLElement, host: HTMLElement, overlays: HTMLElement[]): boolean {
  if (el.parentElement !== document.body) return true
  if (el.contains(host) || overlays.includes(el)) return false
  const style = getComputedStyle(el)
  return (style.position === 'fixed' || style.position === 'absolute') && style.pointerEvents !== 'none'
}

/** The host's place in the page's stacking: a key (z-index first, document order second), and
 *  the parts of `box` under the layers above it (the windows, the drop preview, the positioned
 *  children of <body>) and under the overlays shown. */
export function stacking(host: HTMLElement, box: Box, overlays: HTMLElement[] = []): { z: number, holes: Box[] } {
  const layers = [...document.querySelectorAll<HTMLElement>(`body > *, ${LAYERS}`)].filter(el => bodyLayer(el, host, overlays))
  const key = (el: HTMLElement) => (Number(getComputedStyle(el).zIndex) || 0) * 4096 + layers.indexOf(el)
  const own = host.closest<HTMLElement>(LAYERS)
  const z = own ? key(own) : 0
  const holes: Box[] = []
  const cover = (el: HTMLElement) => {
    const r = el.getBoundingClientRect()
    // Rounded outwards: no sliver of the view shows at the edge of what covers it.
    const left = Math.max(box.x, Math.floor(r.left)), top = Math.max(box.y, Math.floor(r.top))
    const right = Math.min(box.x + box.width, Math.ceil(r.right)), bottom = Math.min(box.y + box.height, Math.ceil(r.bottom))
    if (right > left && bottom > top) holes.push({ x: left - box.x, y: top - box.y, width: right - left, height: bottom - top })
  }
  for (const layer of layers) if (layer !== own && key(layer) > z) cover(layer)
  // A hidden overlay measures 0×0 and covers nothing.
  for (const overlay of overlays) if (overlay.isConnected) cover(overlay)
  return { z, holes }
}

const sameBox = (a: Box, b: Box): boolean => a.x === b.x && a.y === b.y && a.width === b.width && a.height === b.height
const same = (a: Placement | null, b: Placement): boolean =>
  !!a && sameBox(a, b) && a.visible === b.visible && a.z === b.z && a.holes.length === b.holes.length && a.holes.every((h, i) => sameBox(h, b.holes[i]))

/** The state a view starts with, before the backend reports anything. */
export function initial(url: string): WebViewState {
  return { url, title: '', loading: true, progress: 0, canGoBack: false, canGoForward: false, error: null }
}

/** How a backend drives a view; `View` is the state and the listeners. */
interface Backend {
  readonly name: 'native' | 'iframe'
  readonly features: WebViewFeatures
  open(view: View): void
  navigate(view: View, url: string): void
  back(view: View): void
  forward(view: View): void
  reload(view: View): void
  stop(view: View): void
  close(view: View): void
}

let next = 1

const FIELDS = ['url', 'title', 'loading', 'progress', 'canGoBack', 'canGoForward', 'error', 'discarded'] as const satisfies (keyof WebViewState)[]

class View implements WebView {
  readonly id = `wv${next++}`
  readonly host: HTMLElement
  readonly options: WebViewOptions
  state: WebViewState
  adopted = false
  private backend: Backend
  private onClose: (view: View) => void
  private listeners = new Set<() => void>()
  private open = true
  /** The native backend's: the last placement sent. */
  placed: Placement | null = null
  /** The iframe backend's. */
  frame: HTMLIFrameElement | null = null

  constructor(host: HTMLElement, options: WebViewOptions, backend: Backend, onClose: (view: View) => void) {
    this.host = host
    this.options = options
    this.backend = backend
    this.onClose = onClose
    this.state = initial(options.url)
    backend.open(this)
  }

  get url(): string { return this.state.url }
  get title(): string { return this.state.title }
  get loading(): boolean { return this.state.loading }
  get progress(): number { return this.state.progress }
  get canGoBack(): boolean { return this.state.canGoBack }
  get canGoForward(): boolean { return this.state.canGoForward }
  get error(): string | null { return this.state.error }
  get proxy(): WebViewState['proxy'] { return this.state.proxy }
  get discarded(): boolean | undefined { return this.state.discarded }

  /** Merges `patch` into the state and tells the listeners. */
  update(patch: Partial<WebViewState>): void {
    const next: WebViewState = { ...this.state }
    let changed = false
    for (const key of FIELDS) {
      const value = patch[key]
      if (value === undefined || next[key] === value) continue
      Object.assign(next, { [key]: value })
      changed = true
    }
    // An object: the same when its kind and its error are.
    const proxy = patch.proxy
    if (proxy && (proxy.kind !== next.proxy?.kind || proxy.error !== next.proxy?.error)) {
      next.proxy = proxy.error === undefined ? { kind: proxy.kind } : { kind: proxy.kind, error: proxy.error }
      changed = true
    }
    if (!changed) return
    this.state = next
    for (const listener of [...this.listeners]) listener()
  }

  /** A press in the view's content, which the page did not see: told as a pointerdown on the
   *  host, so that whatever focuses a window on a press (the layout) does it here too. */
  press(): void {
    if (!this.open) return
    this.host.dispatchEvent(new PointerEvent('pointerdown', { bubbles: true, cancelable: true, composed: true, button: 0, pointerType: 'mouse', isPrimary: true }))
  }

  navigate(url: string): void { if (this.open) this.backend.navigate(this, url) }
  back(): void { if (this.open) this.backend.back(this) }
  forward(): void { if (this.open) this.backend.forward(this) }
  reload(): void { if (this.open) this.backend.reload(this) }
  stop(): void { if (this.open) this.backend.stop(this) }

  subscribe(listener: () => void): () => void {
    this.listeners.add(listener)
    return () => { this.listeners.delete(listener) }
  }

  dispose(): void {
    if (!this.open) return
    this.open = false
    this.backend.close(this)
    this.listeners.clear()
    this.onClose(this)
  }
}

// --- native: messages to the app, placements that follow the host ---

class Native implements Backend {
  readonly name = 'native'
  readonly features: WebViewFeatures = Object.freeze({ profiles: true, proxy: true })
  private post: (body: Record<string, unknown>) => void
  private overlays: () => HTMLElement[]

  constructor(post: (body: Record<string, unknown>) => void, overlays: () => HTMLElement[]) {
    this.post = post
    this.overlays = overlays
  }

  open(view: View): void {
    const { profile, key } = view.options
    this.post({ op: 'create', id: view.id, url: view.options.url, ...profile && { profile }, ...key && { key } })
    this.place(view)
  }

  /** Measures the host and sends its place when it moved. */
  place(view: View): void {
    const now = placement(view.host, this.overlays())
    if (same(view.placed, now)) return
    view.placed = now
    this.post({ op: 'place', id: view.id, ...now })
  }

  navigate(view: View, url: string): void {
    view.update({ url, loading: true, progress: 0, error: null })
    this.post({ op: 'navigate', id: view.id, url })
  }

  back(view: View): void { this.post({ op: 'back', id: view.id }) }
  forward(view: View): void { this.post({ op: 'forward', id: view.id }) }
  reload(view: View): void { this.post({ op: 'reload', id: view.id }) }
  stop(view: View): void { this.post({ op: 'stop', id: view.id }) }
  close(view: View): void { this.post({ op: 'dispose', id: view.id }) }
}

// --- iframe: the fallback, and what the tests see ---

class Frame implements Backend {
  readonly name = 'iframe'
  readonly features: WebViewFeatures = Object.freeze({ profiles: false, proxy: false })

  open(view: View): void {
    const frame = document.createElement('iframe')
    frame.className = 'webview'
    frame.style.cssText = 'display: block; border: 0; width: 100%; height: 100%; background: transparent;'
    frame.setAttribute('allow', 'fullscreen; clipboard-read; clipboard-write; autoplay')
    frame.addEventListener('load', () => view.update({ loading: false, progress: 1, ...this.readable(frame) }))
    frame.src = view.options.url
    view.frame = frame
    view.host.append(frame)
  }

  /** What a same-origin page lets us read; nothing for a foreign one. */
  private readable(frame: HTMLIFrameElement): Partial<WebViewState> {
    try {
      const doc = frame.contentDocument
      if (!doc) return {}
      return { title: doc.title, url: doc.URL }
    } catch {
      return {}
    }
  }

  /** The frame's window when the page is ours to drive, else null. */
  private inside(view: View): Window | null {
    try {
      const win = view.frame?.contentWindow
      return win && win.location.href !== undefined ? win : null
    } catch {
      return null
    }
  }

  navigate(view: View, url: string): void {
    if (!view.frame) return
    view.update({ url, title: '', loading: true, progress: 0, error: null, canGoBack: false, canGoForward: false })
    view.frame.src = url
  }

  back(view: View): void { this.inside(view)?.history.back() }
  forward(view: View): void { this.inside(view)?.history.forward() }
  reload(view: View): void {
    const win = this.inside(view)
    if (win) win.location.reload()
    else if (view.frame) view.frame.src = view.state.url
    view.update({ loading: true, progress: 0 })
  }

  stop(view: View): void {
    this.inside(view)?.stop()
    view.update({ loading: false })
  }

  close(view: View): void {
    view.frame?.remove()
    view.frame = null
  }
}

/** Settling time of the layout's transitions (left/top/width/height, .08s): a view measured
 *  right after `layout/change` is measured again once they are done. */
const SETTLE_MS = 120

class WebViews extends Service implements WebViewsApi {
  static provide = 'webviews'
  static author = 'dan'
  static tags = ['browser']
  static version = __TILR_VERSION__
  // ui: the overlays (menus, dropdowns) the views leave to the page.
  static inject = ['ui']

  declare state: { views: View[], backend: Backend, native: Native | null, resizer: ResizeObserver | null, timer: ReturnType<typeof setTimeout> | null, frame: number | null }

  constructor(ctx: Context) {
    super(ctx, WebViews.provide)
    const channel = nativeChannel<NativeEvent>(HANDLER, EVENT)
    const native = channel ? new Native(body => channel.post(body), () => ctx.ui.overlays()) : null
    this.state = { views: [], backend: native ?? new Frame(), native, resizer: null, timer: null, frame: null }

    // A press in an iframe is the iframe's: the page sees only its own window losing the focus
    // to it. That is the press, told to the view whose frame now has the focus.
    const onBlur = () => {
      const active = document.activeElement
      const view = active instanceof HTMLIFrameElement ? this.state.views.find(v => v.frame === active) : undefined
      view?.press()
    }
    ctx.effect(() => {
      window.addEventListener('blur', onBlur)
      return () => window.removeEventListener('blur', onBlur)
    }, 'webviews: iframe presses')
    if (!channel || !native) return

    // The app's reports: a view's state, or a page asking for a new window.
    ctx.effect(() => channel.listen(event => this.receive(event)), 'webviews: native events')

    // Whatever moves a host: its own size, the layout, a transition, scrolling, the window.
    const measure = () => this.measure()
    ctx.effect(() => {
      const resizer = this.state.resizer = new ResizeObserver(measure)
      // The children of <body>: a menu panel appended there is a layer (stacking()); shown,
      // hidden (its size) or gone, the views are measured again.
      const children = (nodes: NodeList) => [...nodes].filter((node): node is Element => node instanceof Element)
      for (const child of document.body.children) resizer.observe(child)
      const bodyWatch = new MutationObserver(records => {
        for (const record of records) {
          for (const child of children(record.addedNodes)) resizer.observe(child)
          for (const child of children(record.removedNodes)) resizer.unobserve(child)
        }
        measure()
      })
      bodyWatch.observe(document.body, { childList: true })
      window.addEventListener('resize', measure)
      document.addEventListener('scroll', measure, true)
      document.addEventListener('transitionend', measure, true)
      return () => {
        bodyWatch.disconnect()
        this.state.resizer?.disconnect()
        this.state.resizer = null
        window.removeEventListener('resize', measure)
        document.removeEventListener('scroll', measure, true)
        document.removeEventListener('transitionend', measure, true)
        if (this.state.timer) clearTimeout(this.state.timer)
        if (this.state.frame) cancelAnimationFrame(this.state.frame)
      }
    }, 'webviews: placement')
    ctx.on('layout/change', change => { if (change?.kind !== 'title') measure() })
    ctx.on('ui/overlay', measure)
    // The service going: its views go with it (the app would keep them over a page that forgot them).
    ctx.effect(() => () => { for (const view of [...this.state.views]) view.dispose() }, 'webviews: views')
  }

  get backend(): 'native' | 'iframe' {
    return this.state.backend.name
  }

  get features(): WebViewFeatures {
    return this.state.backend.features
  }

  create(host: HTMLElement, options: WebViewOptions): WebView {
    const { views, backend, native, resizer } = this.state
    const view = new View(host, options, backend, closed => {
      const at = views.indexOf(closed)
      if (at >= 0) views.splice(at, 1)
      resizer?.unobserve(closed.host)
    })
    views.push(view)
    if (native) resizer?.observe(host)
    // this.ctx is the caller's context: the view leaves with the plugin that opened it.
    this.ctx.effect(() => () => view.dispose(), 'webviews.create()')
    return view
  }

  list(): WebView[] {
    return [...this.state.views]
  }

  /** Measures every view on the next frame, and once more when the layout's transitions are done. */
  private measure(): void {
    const { native } = this.state
    if (!native) return
    if (this.state.frame === null) {
      this.state.frame = requestAnimationFrame(() => {
        this.state.frame = null
        for (const view of this.state.views) native.place(view)
      })
    }
    if (this.state.timer) clearTimeout(this.state.timer)
    this.state.timer = setTimeout(() => {
      this.state.timer = null
      for (const view of this.state.views) native.place(view)
    }, SETTLE_MS)
  }

  private receive(detail: NativeEvent): void {
    const view = this.state.views.find(v => v.id === detail.id)
    if (!view) return
    if (detail.type === 'press') return view.press()
    if (detail.type === 'open') {
      if (!detail.open) return
      if (view.options.onOpen) view.options.onOpen(detail.open)
      else view.navigate(detail.open)
      return
    }
    // Adopted: the live view's state, whatever the create asked for.
    if (detail.adopted) view.adopted = true
    const state: Partial<WebViewState> = {}
    for (const key of FIELDS) if (detail[key] !== undefined) Object.assign(state, { [key]: detail[key] })
    if (detail.proxy) state.proxy = detail.proxy
    view.update(state)
  }
}

export default WebViews satisfies TilrPluginClass
